        >
          <td>{{ index + 1 }}</td>
          <td>{{ app.name }}</td>
          <td>{{ app.type.toLowerCase() == "c" ? "Credit" : "Debit" }}</td>
          <td>{{ app.created.split("T")[0] }}</td>
          <td>{{ app.updated.split("T")[0] }}</td>

          <!-- <td>
            <button
