            >
              {{ $t("popups.edit") }}
            </button>
            <a
              class="btn btn-danger btn-sm me-2"
              href="javascript:void(0)"
              role="button"
              @click="deleteMainChartOfAccountsTypes(app)"
              >{{ $t("popups.delete") }}</a
            >
          </td> -->
